{
  "name": "create_refund",
  "description": "为已完成支付的订单发起退款。仅当订单状态为 PAID 或 PARTIALLY_REFUNDED 时可用；建议先以 dry_run=true 调用一次做预检。订单不存在或状态不允许退款时返回结构化错误而非抛出异常。",
  "inputSchema": {
    "type": "object",
    "properties": {
      "order_id": { "type": "string", "description": "订单唯一编号" },
      "amount_cents": { "type": "integer", "minimum": 1, "description": "退款金额，单位为分" },
      "idempotency_key": { "type": "string", "description": "幂等键，同一 key 重复调用返回同一结果" },
      "dry_run": { "type": "boolean", "default": false, "description": "为 true 时只校验不执行" }
    },
    "required": ["order_id", "amount_cents", "idempotency_key"]
  },
  "outputSchema": {
    "type": "object",
    "properties": {
      "refund_id": { "type": "string" },
      "status": { "type": "string", "enum": ["SUCCEEDED", "PENDING", "REJECTED"] },
      "error_code": { "type": "string" },
      "suggestion": { "type": "string" }
    }
  }
}

# 一个最小的 MCP Server 骨架（基于官方 Python SDK 的装饰器风格接口）
from mcp.server.fastmcp import FastMCP

mcp = FastMCP("order-service")

@mcp.tool()
def get_order_status(order_id: str) -> dict:
    """查询订单状态，order_id 为订单唯一编号"""
    status = query_order_service(order_id)
    if status is None:
        # 业务错误：通过结构化返回值携带信息，而不是抛异常中断协议层
        return {"error_code": "ORDER_NOT_FOUND", "message": f"订单 {order_id} 不存在"}
    return {"order_id": order_id, "status": status}

if __name__ == "__main__":
    # 本地场景走 stdio；对外远程部署改为 mcp.run(transport="streamable-http")
    mcp.run(transport="stdio")
